var TYPE_LABELS = { all:"Zote", campaign:"Campaigns", product:"Bidhaa" };
var TYPE_MARKS  = { campaign:"📣", product:"🧪" };
var currentFilter = "all";
var currentPage = 1;
var PAGE_SIZE = 15;

/* ==========================================================================
   ANALYTICS-READY TRACKING FUNCTIONS
   ========================================================================== */
function trackCTA(name, meta){
  // Example future wiring:
  // gtag('event', 'cta_click', { cta_name: name });
  // fbq('trackCustom', 'CTAClick', { cta_name: name });
  if(window.console){ console.log("[trackCTA]", name, meta || ""); }
}

function openSignup(ctaName, item){
  trackCTA(ctaName, item ? {id:item.id, type:item.type} : null);
  window.location.href = APP_URL + "/register";
}

/* ==========================================================================
   SHARE-FLOW MODAL — "SAMBAZA ULIPWE"
   Simulates an account check (all visitors are logged out on this public
   site, so the true result is always "no account yet") then invites signup.
   ========================================================================== */
function spinnerModalHTML(item){
  return '<button class="modal-close" onclick="closeShareFlow()" aria-label="Funga">✕</button>' +
    '<div class="modal-spinner"></div>' +
    '<p class="modal-msg">Inakagua akaunti yako kwa ajili ya <strong>' + item.title + '</strong>...</p>';
}

function noAccountModalHTML(item){
  var msg = 'Huna akaunti ya Woguto bado. Fungua akaunti kwa ada ya TZS 16,000/= ili uanze kusambaza "' + item.title + '" na upate malipo kulingana na masharti ya campaign.';
  return '<button class="modal-close" onclick="closeShareFlow()" aria-label="Funga">✕</button>' +
    '<div class="lock-badge">🔒</div>' +
    '<h4>Huna Akaunti Bado</h4>' +
    '<p class="modal-msg">' + msg + '</p>' +
    '<a href="#" class="btn btn-primary" onclick="event.preventDefault(); openSignup(\'share_flow_' + item.type + '\', ' + '{id:\'' + item.id + '\',type:\'' + item.type + '\'});">Fungua Akaunti – TZS 16,000/=</a>';
}

function openShareFlow(id){
  var item = findItem(id);
  if(!item){ return; }
  trackCTA('share_flow_open', {id:item.id, type:item.type});
  var modal = document.getElementById('share-modal');
  var box = document.getElementById('share-modal-box');
  box.innerHTML = spinnerModalHTML(item);
  modal.classList.add('open');
  setTimeout(function(){
    box.innerHTML = noAccountModalHTML(item);
  }, 1300);
}

function closeShareFlow(){
  document.getElementById('share-modal').classList.remove('open');
}

function toggleMobileNav(){
  var nav = document.getElementById('mobile-nav');
  nav.classList.toggle('open');
}

/* ==========================================================================
   RENDERING
   ========================================================================== */
function allItems(){
  return MOCK_DATA.campaigns.concat(MOCK_DATA.products);
}

function findItem(id){
  var items = allItems();
  for(var i=0;i<items.length;i++){ if(items[i].id === id){ return items[i]; } }
  return null;
}

function estimateViews(item){
  return Math.round(item.participants * 4.3 + 480);
}

function formatCount(n){
  if(n >= 1000){ return (n/1000).toFixed(1).replace(/\.0$/, '') + "K"; }
  return String(n);
}

var SECOND_BTN_LABEL = { campaign:"SAMBAZA ULIPWE", product:"SAMBAZA ULIPWE" };

function cardHTML(item, opts){
  opts = opts || {};
  var locked = !!opts.locked;
  var views = estimateViews(item);
  var secondLabel = SECOND_BTN_LABEL[item.type] || "SAMBAZA ULIPWE";
  return '' +
    '<div class="card">' +
      '<a href="?type=' + item.type + '&amp;id=' + item.id + '" ' +
         'onclick="event.preventDefault(); goToDetail(\'' + item.type + '\',\'' + item.id + '\');">' +
        '<div class="card-media">' +
          '<img src="' + item.image + '" alt="' + item.title + '" loading="lazy" />' +
          (locked ? '<span class="locked-tag">🔒 Wanachama</span>' : '') +
          '<span class="type-mark">' + TYPE_MARKS[item.type] + '</span>' +
          '<span class="cat-badge">' + item.category + '</span>' +
        '</div>' +
        '<div class="card-body">' +
          '<h3>' + item.title + '</h3>' +
          '<div class="card-stats">' +
            '<span>👁 ' + formatCount(views) + '</span>' +
            '<span>👥 ' + formatCount(item.participants) + '</span>' +
          '</div>' +
          '<div class="card-price">' + item.priceLabel + (item.priceLabel.indexOf('TZS') !== -1 ? '<span class="unit">/ ushiriki</span>' : '') + '</div>' +
        '</div>' +
      '</a>' +
      '<div class="card-actions" style="padding:0 14px 14px;">' +
        '<button class="btn-card-outline" onclick="event.preventDefault(); goToDetail(\'' + item.type + '\',\'' + item.id + '\');">ANGALIA</button>' +
        '<button class="btn-card-solid" onclick="event.preventDefault(); openShareFlow(\'' + item.id + '\');">' + secondLabel + '</button>' +
      '</div>' +
    '</div>';
}

function renderFilterTabs(){
  var order = ["all","campaign","product"];
  var html = order.map(function(key){
    return '<button class="filter-tab' + (key === currentFilter ? ' active' : '') + '" ' +
           'onclick="setFilter(\'' + key + '\')">' + TYPE_LABELS[key] + '</button>';
  }).join('');
  document.getElementById('filter-tabs').innerHTML = html;
}

function renderListingGrid(){
  var items = allItems();
  if(currentFilter !== 'all'){
    items = items.filter(function(i){ return i.type === currentFilter; });
  }
  var totalPages = Math.max(1, Math.ceil(items.length / PAGE_SIZE));
  if(currentPage > totalPages){ currentPage = totalPages; }
  if(currentPage < 1){ currentPage = 1; }
  var start = (currentPage - 1) * PAGE_SIZE;
  var pageItems = items.slice(start, start + PAGE_SIZE);
  document.getElementById('listing-grid').innerHTML = pageItems.map(function(i){ return cardHTML(i); }).join('');
  renderPagination(totalPages);
}

function renderPagination(totalPages){
  var el = document.getElementById('pagination');
  if(!el){ return; }
  if(totalPages <= 1){ el.innerHTML = ''; return; }
  var html = '<button class="page-btn" onclick="goToPage(' + (currentPage - 1) + ')"' + (currentPage === 1 ? ' disabled' : '') + '>‹</button>';
  for(var p = 1; p <= totalPages; p++){
    html += '<button class="page-btn' + (p === currentPage ? ' active' : '') + '" onclick="goToPage(' + p + ')">' + p + '</button>';
  }
  html += '<button class="page-btn" onclick="goToPage(' + (currentPage + 1) + ')"' + (currentPage === totalPages ? ' disabled' : '') + '>›</button>';
  el.innerHTML = html;
}

function goToPage(p){
  currentPage = p;
  trackCTA('listing_page', {page:p});
  renderListingGrid();
  var section = document.getElementById('fursa');
  if(section){ section.scrollIntoView({behavior:'smooth', block:'start'}); }
}

function setFilter(key){
  currentFilter = key;
  currentPage = 1;
  trackCTA('filter_' + key);
  renderFilterTabs();
  renderListingGrid();
}

function renderHome(){
  renderFilterTabs();
  renderListingGrid();
}

function renderDetail(item){
  document.title = item.title + " — Woguto";
  var metaDesc = document.querySelector('meta[name="description"]');
  if(metaDesc){ metaDesc.setAttribute('content', item.shortDescription); }
  var ogTitle = document.querySelector('meta[property="og:title"]');
  if(ogTitle){ ogTitle.setAttribute('content', item.title + " — Woguto"); }
  var ogDesc = document.querySelector('meta[property="og:description"]');
  if(ogDesc){ ogDesc.setAttribute('content', item.shortDescription); }

  document.getElementById('detail-category').textContent = item.category;
  document.getElementById('detail-title').textContent = item.title;
  document.getElementById('detail-hero').style.backgroundImage = "url('" + item.image + "')";
  document.getElementById('detail-lede').textContent = item.fullDescription;
  document.getElementById('detail-participants').textContent = item.participants.toLocaleString();
  document.getElementById('detail-deadline').textContent = item.deadline;
  document.getElementById('detail-reward').textContent = item.reward;
  document.getElementById('detail-followers').textContent = item.followersRequired;

  document.getElementById('detail-locked-list').innerHTML =
    item.lockedDetails.map(function(line){ return '<li><span>🔒</span><span>' + line + '</span></li>'; }).join('');

  var unlockBtn = document.getElementById('detail-unlock-btn');
  unlockBtn.onclick = function(e){ e.preventDefault(); openSignup(item.type + '_signup', item); return false; };

  var secondaryCta = document.getElementById('detail-secondary-cta');
  secondaryCta.textContent = "SAMBAZA ULIPWE";
  secondaryCta.onclick = function(e){ e.preventDefault(); openShareFlow(item.id); return false; };

  var waBtn = document.getElementById('detail-whatsapp-btn');
  waBtn.onclick = function(){ shareToWhatsApp(item); };
}

/* ==========================================================================
   FEATURED SLIDER
   ========================================================================== */
var sliderIndex = 0;
var sliderTimer = null;

function renderSlider(){
  var slides = [MOCK_DATA.campaigns[0], MOCK_DATA.campaigns[1], MOCK_DATA.campaigns[3]];
  var slider = document.getElementById('featured-slider');
  var dots = document.getElementById('slider-dots');
  var slideHtml = slides.map(function(s, idx){
    return '<div class="slide' + (idx === 0 ? ' active' : '') + '" data-idx="' + idx + '" style="background-image:url(\'' + s.image + '\');">' +
      '<div class="slide-inner">' +
        '<span class="cat-pill">' + s.category + '</span>' +
        '<h3>' + s.title + '</h3>' +
        '<p>' + s.shortDescription + '</p>' +
        '<div class="slide-actions">' +
          '<a href="#" class="btn btn-secondary" onclick="event.preventDefault(); goToDetail(\'' + s.type + '\',\'' + s.id + '\');">ANGALIA</a>' +
          '<a href="#" class="btn" onclick="event.preventDefault(); openShareFlow(\'' + s.id + '\');">SAMBAZA ULIPWE</a>' +
        '</div>' +
      '</div>' +
    '</div>';
  }).join('');
  slider.innerHTML = slideHtml + '<div class="slide-dots" id="slider-dots"></div>';
  var dotHtml = slides.map(function(s, idx){
    return '<button class="' + (idx === 0 ? 'active' : '') + '" onclick="goToSlide(' + idx + ')" aria-label="Slide ' + (idx+1) + '"></button>';
  }).join('');
  document.getElementById('slider-dots').innerHTML = dotHtml;
  startSliderAuto();
}

function goToSlide(idx){
  sliderIndex = idx;
  var slides = document.querySelectorAll('#featured-slider .slide');
  var dots = document.querySelectorAll('#slider-dots button');
  for(var i=0;i<slides.length;i++){ slides[i].classList.toggle('active', i === idx); }
  for(var j=0;j<dots.length;j++){ dots[j].classList.toggle('active', j === idx); }
}

function startSliderAuto(){
  if(sliderTimer){ clearInterval(sliderTimer); }
  sliderTimer = setInterval(function(){
    var slides = document.querySelectorAll('#featured-slider .slide');
    if(!slides.length){ return; }
    sliderIndex = (sliderIndex + 1) % slides.length;
    goToSlide(sliderIndex);
  }, 5000);
}

/* ==========================================================================
   WHATSAPP VIRAL LOOP
   ========================================================================== */
function shareToWhatsApp(item){
  trackCTA('whatsapp_share', {id:item.id, type:item.type});
  var url = window.location.href;
  var text = "🔥 Kuna opportunity nimeiona Woguto.\n" + item.title + " — angalia hii hapa: " + url;
  var waUrl = "https://wa.me/?text=" + encodeURIComponent(text);
  window.open(waUrl, '_blank');
}

/* ==========================================================================
   ROUTING — reads type and id from the URL
   ========================================================================== */
function goToDetail(type, id){
  var url = new URL(window.location.href);
  url.searchParams.set('type', type);
  url.searchParams.set('id', id);
  window.history.pushState({}, '', url);
  route();
  window.scrollTo({top:0, behavior:'instant'});
}

function goHome(e){
  if(e){ e.preventDefault(); }
  var url = new URL(window.location.href);
  url.searchParams.delete('type');
  url.searchParams.delete('id');
  window.history.pushState({}, '', url);
  route();
  window.scrollTo({top:0, behavior:'instant'});
}

function route(){
  var params = new URLSearchParams(window.location.search);
  var type = params.get('type');
  var id = params.get('id');
  var item = id ? findItem(id) : null;

  var homeView = document.getElementById('home-view');
  var detailView = document.getElementById('detail-view');

  if(type && item){
    homeView.classList.add('hidden');
    detailView.classList.add('active');
    renderDetail(item);
  } else {
    homeView.classList.remove('hidden');
    detailView.classList.remove('active');
  }
}

window.addEventListener('popstate', route);

