var NETWORKS = [
  { name:"M-Pesa", logo:"data:image/png;base64," },
  { name:"HaloPesa", logo:"data:image/png;base64," },
  { name:"Mixx by Yas", logo:"data:image/png;base64," },
  { name:"Airtel Money", logo:"data:image/png;base64," }
];
var TX_LAST_NAMES = ["M.","J.","H.","S.","K.","N.","O.","B.","R.","T."];

function maskedPhone(){
  var last3 = String(Math.floor(100 + Math.random() * 900));
  return "*********" + last3;
}

function randomTxTime(){
  var mins = Math.floor(1 + Math.random() * 58);
  return "Dakika " + mins + " zilizopita";
}

function randomTxAmount(){
  var amt = Math.round((3000 + Math.random() * 42000) / 500) * 500;
  return "TZS " + amt.toLocaleString();
}

function renderTxRow(rowEl){
  var network = randomFrom(NETWORKS);
  var name = randomFrom(TICKER_NAMES) + " " + randomFrom(TX_LAST_NAMES);
  rowEl.style.opacity = 0;
  setTimeout(function(){
    rowEl.innerHTML =
      '<div class="tx-logo"><img src="' + network.logo + '" alt="' + network.name + '" /></div>' +
      '<div class="tx-main">' +
        '<div class="tx-name">' + name + '</div>' +
        '<div class="tx-phone">' + maskedPhone() + '</div>' +
      '</div>' +
      '<div class="tx-side">' +
        '<div class="tx-amount">' + randomTxAmount() + '</div>' +
        '<div class="tx-time">' + randomTxTime() + '</div>' +
      '</div>';
    rowEl.style.opacity = 1;
  }, 200);
}

function startTxFeed(){
  var rows = document.querySelectorAll('.tx-row');
  if(!rows.length){ return; }
  for(var i=0;i<rows.length;i++){ renderTxRow(rows[i]); }
  setInterval(function(){
    var idx = Math.floor(Math.random() * rows.length);
    renderTxRow(rows[idx]);
  }, 3200);
}

/* ==========================================================================
   LIVE DATE/TIME — top utility bar (Swahili day/month names)
   ========================================================================== */
var SW_DAYS = ["Jumapili","Jumatatu","Jumanne","Jumatano","Alhamisi","Ijumaa","Jumamosi"];
var SW_MONTHS = ["Januari","Februari","Machi","Aprili","Mei","Juni","Julai","Agosti","Septemba","Oktoba","Novemba","Desemba"];

function pad2(n){ return n < 10 ? "0" + n : String(n); }

function updateDateTime(){
  var el = document.getElementById('live-datetime');
  if(!el){ return; }
  var now = new Date();
  var text = SW_DAYS[now.getDay()] + ", " + now.getDate() + " " + SW_MONTHS[now.getMonth()] + " " + now.getFullYear() +
    " · " + pad2(now.getHours()) + ":" + pad2(now.getMinutes()) + ":" + pad2(now.getSeconds());
  el.textContent = text;
}

function startClock(){
  updateDateTime();
  setInterval(updateDateTime, 1000);
}

